}

int cmpInt(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int lower_bound_x(Point *p, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) / 2;
        if (p[m].x < x) l = m + 1;
        else r = m;
    }
    return l;
}

int upper_bound_x(Point *p, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) / 2;
        if (p[m].x <= x) l = m + 1;
        else r = m;
    }
    return l;
}

