// Compare function for sorting by x then y
bool compareX(const Point& a, const Point& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

bool compareY(const Point& a, const Point& b) {
    return a.y < b.y || (a.y == b.y && a.x < b.x);
}

// Build a kd-tree node recursively
struct KDNode {
    Point point;
    KDNode *left, *right;
    int axis; // 0 for x, 1 for y

    KDNode(Point p) : point(p), left(nullptr), right(nullptr), axis(0) {}
};

KDNode* buildKDTree(vector<Point>& points, int depth, int l, int r) {
    if (l > r) return nullptr;

    int axis = depth % 2;
    int mid = (l + r) / 2;

    // Sort points based on current axis
    if (axis == 0) {
        nth_element(points.begin() + l, points.begin() + mid, points.begin() + r + 1, compareX);
    } else {
        nth_element(points.begin() + l, points.begin() + mid, points.begin() + r + 1, compareY);
    }

    KDNode* node = new KDNode(points[mid]);
    node->axis = axis;
    node->left = buildKDTree(points, depth + 1, l, mid - 1);
    node->right = buildKDTree(points, depth + 1, mid + 1, r);

    return node;
}

void rangeSearch(KDNode* node, int x1, int y1, int x2, int y2, vector<Point>& result) {
    if (node == nullptr) return;

    int x = node->point.x;
    int y = node->point.y;

    // Check if current point is within range
    if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
        result.push_back(node->point);
    }

    // Prune and search subtrees
    if (node->axis == 0) {
        // x-axis split
        if (x1 <= x) {
            rangeSearch(node->left, x1, y1, x2, y2, result);
        }
        if (x2 >= x) {
            rangeSearch(node->right, x1, y1, x2, y2, result);
        }
    } else {
        // y-axis split
        if (y1 <= y) {
            rangeSearch(node->left, x1, y1, x2, y2, result);
        }
        if (y2 >= y) {
            rangeSearch(node->right, x1, y1, x2, y2, result);
        }
    }
}

