Node* build(vector<Point>& pts, int l, int r, int depth) {
    if (l > r) return nullptr;
    int mid = (l + r) / 2;
    if (depth % 2 == 0) {
        nth_element(pts.begin() + l, pts.begin() + mid, pts.begin() + r + 1,
            [](const Point& a, const Point& b) { return a.x < b.x; });
    } else {
        nth_element(pts.begin() + l, pts.begin() + mid, pts.begin() + r + 1,
            [](const Point& a, const Point& b) { return a.y < b.y; });
    }
    Node* node = new Node(pts[mid].x, pts[mid].y, pts[mid].id);
    node->left = build(pts, l, mid - 1, depth + 1);
    node->right = build(pts, mid + 1, r, depth + 1);
    return node;
}

vector<int> result;

void search(Node* node, int sx, int tx, int sy, int ty, int depth) {
    if (!node) return;
    int x = node->x, y = node->y;
    if (sx <= x && x <= tx && sy <= y && y <= ty) {
        result.push_back(node->id);
    }
    if (depth % 2 == 0) {
        // split on x
        if (sx <= x) search(node->left, sx, tx, sy, ty, depth + 1);
        if (tx >= x) search(node->right, sx, tx, sy, ty, depth + 1);
    } else {
        // split on y
        if (sy <= y) search(node->left, sx, tx, sy, ty, depth + 1);
        if (ty >= y) search(node->right, sx, tx, sy, ty, depth + 1);
    }
}

