/*
  AOJ / DSL_2_C : Range Search

  We are given n points (x, y), each with its input index.
  For each query rectangle [sx, tx] x [sy, ty], output indices of points
  inside the rectangle in ascending order, then a blank line.

  Standard solution:
  - Sort points by x.
  - Build a segment tree over x-order.
  - Each node stores points in its range sorted by y.
  - For a query:
      * collect segment tree nodes fully covered by x-range
      * in each node, binary search y-range and report matching point indices
  - Sort reported indices before output.

  Complexity:
  - Build: O(n log n)
  - Query: O(log^2 n + k log k) roughly, where k is number of reported points
*/

struct Point {
    int x, y, id;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Point> pts(n);
    for (int i = 0; i < n; i++) {
        cin >> pts[i].x >> pts[i].y;
        pts[i].id = i;
    }

    sort(pts.begin(), pts.end(), [](const Point& a, const Point& b) {
        if (a.x != b.x) return a.x < b.x;
        if (a.y != b.y) return a.y < b.y;
        return a.id < b.id;
    });

    int sz = 1;
    while (sz < n) sz <<= 1;

    vector<vector<pair<int,int>>> seg(2 * sz); // (y, id)

    for (int i = 0; i < n; i++) {
        seg[sz + i].push_back({pts[i].y, pts[i].id});
    }
    for (int i = sz - 1; i >= 1; i--) {
        auto &L = seg[i << 1], &R = seg[i << 1 | 1];
        seg[i].resize(L.size() + R.size());
        merge(L.begin(), L.end(), R.begin(), R.end(), seg[i].begin());
    }

    int q;
    cin >> q;
    while (q--) {
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;

        int l = lower_bound(pts.begin(), pts.end(), sx, [](const Point& p, int v) {
            return p.x < v;
        }) - pts.begin();

        int r = upper_bound(pts.begin(), pts.end(), tx, [](int v, const Point& p) {
            return v < p.x;
        }) - pts.begin();

        vector<int> ans;

        for (l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                auto &vec = seg[l++];
                auto it1 = lower_bound(vec.begin(), vec.end(), make_pair(sy, -1));
                auto it2 = upper_bound(vec.begin(), vec.end(), make_pair(ty, INT_MAX));
                for (auto it = it1; it != it2; ++it) ans.push_back(it->second);
            }
            if (r & 1) {
                auto &vec = seg[--r];
                auto it1 = lower_bound(vec.begin(), vec.end(), make_pair(sy, -1));
                auto it2 = upper_bound(vec.begin(), vec.end(), make_pair(ty, INT_MAX));
                for (auto it = it1; it != it2; ++it) ans.push_back(it->second);
            }
        }

        sort(ans.begin(), ans.end());
        for (int id : ans) cout << id << '\n';
        cout << '\n';
    }

    return 0;
}

