        left[nodeId] = buildKD(leftIndices, 0, leftIndices.length - 1, depth + 1, nodeX, nodeY, left, right, counter);
        right[nodeId] = buildKD(rightIndices, 0, rightIndices.length - 1, depth + 1, nodeX, nodeY, left, right, counter);

        return nodeId;
    }

    static void searchKD(int node, int sx, int tx, int sy, int ty, int depth, int[] nodeX, int[] nodeY, int[] left, int[] right) {
        if (node == -1) return;

        int x = nodeX[node];
        int y = nodeY[node];

        if (sx <= x && x <= tx && sy <= y && y <= ty) {
            result.add(new int[]{x, y});
        }

        int axis = depth % 2;
        if (axis == 0) {
            if (sx <= x) searchKD(left[node], sx, tx, sy, ty, depth + 1, nodeX, nodeY, left, right);
            if (tx >= x) searchKD(right[node], sx, tx, sy, ty, depth + 1, nodeX, nodeY, left, right);
        } else {
            if (sy <= y) searchKD(left[node], sx, tx, sy, ty, depth + 1, nodeX, nodeY, left, right);
            if (ty >= y) searchKD(right[node], sx, tx, sy, ty, depth + 1, nodeX, nodeY, left, right);
        }
    }
}

import java.io.*;
import java.util.*;

/*
 * 2D Range Search (static set of points)
 *
 * Input format:
 * n
 * x1 y1
 * ...
 * xn yn
 * q
 * sx tx sy ty   // query rectangle: sx <= x <= tx and sy <= y <= ty
 * ...
 *
 * For each query, output the ids (0-based indices in input order) of points
 * inside the rectangle, one per line, sorted by x then y then id.
 * Print an empty line after each query.
 *
 * This is the standard AOJ DSL_2_C style solution using a KD-Tree.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        int x, y, id;
        Point(int x, int y, int id) {
            this.x = x;
            this.y = y;
            this.id = id;
        }
    }

    static class Node {
        Point p;
        Node left, right;
        Node(Point p) {
            this.p = p;
        }
    }

    static Point[] pts;

    static Node build(int l, int r, int depth) {
        if (l >= r) return null;
        int mid = (l + r) >>> 1;

        if ((depth & 1) == 0) {
            Arrays.sort(pts, l, r, (a, b) -> {
                if (a.x != b.x) return Integer.compare(a.x, b.x);
                if (a.y != b.y) return Integer.compare(a.y, b.y);
                return Integer.compare(a.id, b.id);
            });
        } else {
            Arrays.sort(pts, l, r, (a, b) -> {
                if (a.y != b.y) return Integer.compare(a.y, b.y);
                if (a.x != b.x) return Integer.compare(a.x, b.x);
                return Integer.compare(a.id, b.id);
            });
        }

        Node node = new Node(pts[mid]);
        node.left = build(l, mid, depth + 1);
        node.right = build(mid + 1, r, depth + 1);
        return node;
    }

    static void find(Node node, int sx, int tx, int sy, int ty, int depth, List<Point> ans) {
        if (node == null) return;

        Point p = node.p;
        if (sx <= p.x && p.x <= tx && sy <= p.y && p.y <= ty) {
            ans.add(p);
        }

        if ((depth & 1) == 0) {
            if (node.left != null && sx <= p.x) find(node.left, sx, tx, sy, ty, depth + 1, ans);
            if (node.right != null && p.x <= tx) find(node.right, sx, tx, sy, ty, depth + 1, ans);
        } else {
            if (node.left != null && sy <= p.y) find(node.left, sx, tx, sy, ty, depth + 1, ans);
            if (node.right != null && p.y <= ty) find(node.right, sx, tx, sy, ty, depth + 1, ans);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        pts = new Point[n];
        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            pts[i] = new Point(x, y, i);
        }

        Node root = build(0, n, 0);

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            int sx = fs.nextInt();
            int tx = fs.nextInt();
            int sy = fs.nextInt();
            int ty = fs.nextInt();

            List<Point> ans = new ArrayList<>();
            find(root, sx, tx, sy, ty, 0, ans);

            ans.sort((a, b) -> Integer.compare(a.id, b.id));
            for (Point p : ans) {
                out.append(p.id).append('\n');
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys


class KDNode:
    __slots__ = ("idx", "axis", "left", "right")

    def __init__(self, idx=-1, axis=0, left=None, right=None):
        self.idx = idx
        self.axis = axis
        self.left = left
        self.right = right


def build(points, ids, depth=0):
    if not ids:
        return None
    axis = depth % 2
    ids.sort(key=lambda i: points[i][axis])
    mid = len(ids) // 2
    node = KDNode(ids[mid], axis)
    node.left = build(points, ids[:mid], depth + 1)
    node.right = build(points, ids[mid + 1 :], depth + 1)
    return node


def query(points, node, sx, tx, sy, ty, ans):
    if node is None:
        return

    x, y = points[node.idx]
    if sx <= x <= tx and sy <= y <= ty:
        ans.append(node.idx)

    if node.axis == 0:
        if node.left is not None and sx <= x:
            query(points, node.left, sx, tx, sy, ty, ans)
        if node.right is not None and x <= tx:
            query(points, node.right, sx, tx, sy, ty, ans)
    else:
        if node.left is not None and sy <= y:
            query(points, node.left, sx, tx, sy, ty, ans)
        if node.right is not None and y <= ty:
            query(points, node.right, sx, tx, sy, ty, ans)


def main():
    input = sys.stdin.readline

    n = int(input())
    points = [tuple(map(int, input().split())) for _ in range(n)]

    root = build(points, list(range(n)))

    q = int(input())
    out = []
    for _ in range(q):
        sx, tx, sy, ty = map(int, input().split())
        ans = []
        query(points, root, sx, tx, sy, ty, ans)
        ans.sort()
        out.extend(str(i) for i in ans)
        out.append("")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
